-- RRTrack 2.0 - ATUALIZAR-2026-09-30-F-COMPACTO (versao compacta)
-- O SQL Editor do Supabase corta o script na linha 100; esta versao cabe.
-- Mesmo conteudo de ATUALIZAR-2026-09-30-F.sql, sem as quebras de linha. Cole tudo e rode.

alter table public.meta_insights_cache drop constraint if exists meta_insights_level_valido; alter table public.meta_insights_cache add constraint meta_insights_level_valido check (level in ('campaign', 'adset', 'ad', 'diario')); comment on column public.meta_insights_cache.level is 'O grão do que está guardado. `campaign`/`adset`/`ad` são níveis da Meta e montam a árvore; `diario` é NOSSO — a série de gasto por dia, pedida com time_increment=1. Precisa ser distinto porque a árvore e a série cobrem a mesma conta e o mesmo período: sob a mesma chave, uma sobrescreveria a outra a cada troca de tela.'; do $conf$ declare v_def text; begin select pg_get_constraintdef(c.oid) into v_def from pg_constraint c join pg_class t on t.oid = c.conrelid join pg_namespace n on n.oid = t.relnamespace where n.nspname = 'public' and t.relname = 'meta_insights_cache' and c.conname = 'meta_insights_level_valido'; if v_def is null then raise notice ' [FALHA] o check sumiu — me mande este relatório.'; elsif v_def like '%diario%' then raise notice ' [ok] o cache aceita a série diária de gasto.'; raise notice ' Abra a visão geral: o quadro de receita e investimento'; raise notice ' por dia já deve estar desenhando as duas linhas.'; else raise notice ' [FALHA] o check ficou sem `diario`: %', v_def; end if; end; $conf$;
